  const cast=d.characters.map((c,i)=>{const next='character-'+crypto.randomUUID();castMap.set(c.id||i,next);return{...c,id:next,projectId:id,projectTitle:d.title,role:'Character',archetype:'Imported profile',image:null,referenceReady:false,color:'#839818',prompt:c.prompt||''};});

