  for(const [items,type] of [[cast,'character'],[places,'location'],[nextScenes,'scene']])for(const item of items){if(item.importFile){const a=await importImage(item.importFile,{type,ownerId:item.id,storyId:id,prompt:'Imported with source manuscript',coverage:type==='character'?['portrait-or-sheet-unverified']:['environment']});if(type==='scene')item.approvedImageId=a.id;else await approveReference(a.id);}delete item.importFile;}

