  for(const t of importedThemes){if(t.importFile){const a=await importImage(t.importFile,{type:'theme',ownerId:t.id,storyId:id,prompt:t.description||t.name});t.referenceAssetId=a.id;}delete t.importFile;}

  let sourceDocument=d.sourceDocument?{...d.sourceDocument,images:undefined,extractedImageCount:d.sourceDocument.images?.length||0,originalName:d.sourceFile?.name}:null;

  if(d.sourceFile){const a=await saveAsset({id:crypto.randomUUID(),type:'source',ownerId:id,storyId:id,blob:d.sourceFile,createdAt:new Date().toISOString(),source:'Original PDF',approved:false});sourceDocument.sourceAssetId=a.id;}

  const created={id,title:d.title,description:d.mode==='pdf'?'Imported manuscript · review story details':'Your visual story space',genre:'Story project',characterIds:cast.map(c=>c.id),locationIds:places.map(l=>l.id),scenes:nextScenes,themes:importedThemes,sourceDocument,importGaps:d.importGaps||[]};

