 async function exportMedia(){try{const records=assets;const encoded=await Promise.all(records.map(async a=>{const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;Promise.resolve(a.blob||fetch(a.url,{credentials:'same-origin'}).then(r=>r.blob())).then(b=>r.readAsDataURL(b)).catch(reject);});const {blob,...rest}=a;return {...rest,data};}));const b=new Blob([JSON.stringify({format:'enchanted-quill-media-v1',assets:encoded,projects,characters,locations,customLocations:locations.filter(l=>!seedLocations.some(s=>s.id===l.id))})],{type:'application/json'});const u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='enchanted-quill-media-backup.json';a.click();URL.revokeObjectURL(u);notify('Media and story backup exported');}catch(e){notify('Backup failed: '+e.message);}}

