 let projectId=$state('midnight'), page=$state('overview'), view=$state('canvas'), selected=$state(1), collapsed=$state(false), mobileNav=$state(false), inspectorOpen=$state(true), inspectorWidth=$state(280), compact=$state(false), ready=$state(false), saveStatus=$state('Saved on this device'), toast=$state(''), commandOpen=$state(false), commandQuery=$state(''), sceneQuery=$state(''), filter=$state('all'), inspectorTab=$state('details'), selectedEntity=$state(null), modal=$state(''), newTitle=$state(''), newDescription=$state(''), sheetCharacter=$state(null), sheetZoom=$state(false), playing=$state(false), playId=$state(1), history=$state([]), fontSize=$state(19), focusMode=$state(false), dragId=$state(null), dragOver=$state(null), context=$state(null), deleted=$state(null), notificationOpen=$state(false);

