 const primaryNav=[{id:'overview',label:'Overview',icon:LayoutDashboard},{id:'projects',label:'Projects',icon:FolderOpen}];

 const storyNav=[{id:'scenes',label:'Story workspace',icon:Clapperboard},{id:'characters',label:'Characters',icon:Users},{id:'locations',label:'Locations',icon:MapPin},{id:'themes',label:'Themes & threads',icon:Layers3}];

 let intelligenceNav=$derived([{id:'memory',label:'AI memory',icon:BrainCircuit},{id:'world',label:'World database',icon:Database},{id:'health',label:'Narrative health',icon:HeartPulse},{id:'prompts',label:'Prompt library',icon:WandSparkles},{id:'generation',label:'Generation studio',icon:WandSparkles},{id:'credits',label:'Plans & credits',icon:Layers3},{id:'cloud',label:'Saved cloud projects',icon:Database},...(userSession?.user?.admin?[{id:'provider',label:'AI Provider Settings',icon:ShieldCheck}]:[])]);

