 let commands=$derived([...primaryNav,...storyNav,...intelligenceNav,{id:'activity',label:'Recent activity',icon:Activity}].map(p=>({...p,group:'Navigate',run:()=>navigate(p.id)})).concat(scenes.map(s=>({id:'scene-'+s.id,label:s.title,group:'Scenes',icon:Clapperboard,run:()=>openScene(s.id)}))).concat([{id:'new',label:'Create a new scene',group:'Actions',icon:Plus,run:addScene},{id:'play',label:'Preview your story',group:'Actions',icon:Play,run:()=>startReading()},{id:'export',label:'Export story',group:'Actions',icon:Download,run:exportStory}]).filter(c=>c.label.toLowerCase().includes(commandQuery.toLowerCase())));

 onMount(()=>{try{const savedTheme=localStorage.getItem('quill-theme');if(savedTheme==='dark'||savedTheme==='light')theme=savedTheme;}catch{}refreshAssets();apiRequest('/session').then(s=>{userSession=s;loadCloud();}).catch(()=>{});try{const d=JSON.parse(localStorage.getItem('quill-studio-v1'));if(d?.projects?.length){projects=d.projects;localBackups=d.localBackups||[];if(Array.isArray(d.characters))characters=d.characters;if(Array.isArray(d.locations))locations=d.locations;if(Array.isArray(d.customLocations))locations.push(...d.customLocations.filter(l=>!locations.some(x=>x.id===l.id)));projectId=d.projectId||d.projects[0].id;notes=d.notes||notes;activity=d.activity||activity;collapsed=!!d.collapsed;inspectorWidth=d.inspectorWidth||280;}else{const old=JSON.parse(localStorage.getItem('enchanted-quill'));if(old?.scenes?.length){projects[0].title=old.title||projects[0].title;projects[0].scenes=old.scenes.map((s,i)=>({...s,thread:s.thread||threads[i%3].id,status:s.status||'Draft',location:s.location||locations[i%3].name}));}}}catch{}let libraryAdded=false;for(const edition of storyLibrary){if(!projects.some(p=>p.id===edition.id)){projects.push(clone(edition));libraryAdded=true;}}if(libraryAdded)projectId="library-midnight";for(const p of projects){for(const sc of p.scenes){if(!sc.visualSchema){sc.locationId=locations.find(l=>l.name===sc.location)?.id||'';sc.characterIds=p.characterIds?.slice(0,1)||[];sc.visualSchema=1;sc.legacyImage=sc.image;delete sc.image;}}}applyArtwork(projects,characters,locations);applyStoryGuides(projects);selected=project.scenes[0]?.id||1;const media=matchMedia('(max-width:1180px)');compact=media.matches;if(compact)inspectorOpen=false;const change=()=>{compact=media.matches;if(compact)inspectorOpen=false;};media.addEventListener('change',change);ready=true;return()=>media.removeEventListener('change',change);});

 $effect(()=>{if(!ready)return;const data=JSON.stringify({projects,projectId,notes,activity,collapsed,inspectorWidth,customLocations:locations.filter(l=>!seedLocations.some(s=>s.id===l.id)),characters,locations,localBackups});saveStatus='Saving changes';const timer=setTimeout(()=>{try{localStorage.setItem('quill-studio-v1',data);saveStatus='Saved on this device';}catch{saveStatus='Storage full. Export a backup';}},400);return()=>clearTimeout(timer);});

 const syncedProjects=new Map();let cloudSyncBusy=false;

 $effect(()=>{if(!ready||!project.cloudRevision)return;const id=project.id,revision=project.cloudRevision,copy=clone(project);delete copy.cloudRevision;const payload={...copy,savedCharacters:characters.filter(c=>c.projectId===id||copy.characterIds?.includes(c.id)),savedLocations:locations.filter(l=>l.projectId===id||copy.locationIds?.includes(l.id))},signature=JSON.stringify(payload);if(syncedProjects.get(id)===signature)return;const timer=setTimeout(async()=>{if(cloudSyncBusy)return;cloudSyncBusy=true;try{const r=await apiRequest('/projects/'+encodeURIComponent(id),{method:'PUT',body:JSON.stringify({project:payload,revision})});syncedProjects.set(id,signature);const p=projects.find(p=>p.id===id);if(p)p.cloudRevision=r.revision;cloudStatus='Cloud autosave active';}catch(e){cloudStatus='Cloud sync paused: '+e.message;}finally{cloudSyncBusy=false;}},1800);return()=>clearTimeout(timer);});

