 function keydown(e){if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();commandOpen=!commandOpen;commandQuery='';}if(e.key==='Escape'){commandOpen=false;playing=false;modal='';mobileNav=false;sheetCharacter=null;context=null;notificationOpen=false;focusMode=false;}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();startReading(selected);}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();notify(saveStatus==='Saved on this device'?'Everything is saved on this device':saveStatus);}}

 function exportStory(){const blob=new Blob([JSON.stringify({title:project.title,scenes,notes},null,2)],{type:'application/json'}),href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download=project.title.toLowerCase().replace(/[^a-z0-9]+/g,'-')+'.json';a.click();URL.revokeObjectURL(href);notify('Story exported');}

 async function importStory(e){const f=e.target.files?.[0];if(!f)return;try{const d=JSON.parse(await f.text());if(typeof d.title!=='string'||!Array.isArray(d.scenes)||!d.scenes.length)throw Error();const ids=new Set();for(const s of d.scenes){if(!Number.isSafeInteger(s.id)||ids.has(s.id)||typeof s.title!=='string'||typeof s.text!=='string'||!Array.isArray(s.choices))throw Error();ids.add(s.id);}for(const s of d.scenes)for(const c of s.choices)if(typeof c.label!=='string'||!ids.has(c.target))throw Error();const id='project-'+Date.now();projects.push({id,title:d.title,description:'Imported story',genre:'Story project',scenes:d.scenes.map((s,i)=>({...s,thread:s.thread||threads[i%3].id,status:s.status||'Draft'}))});projectId=id;selected=d.scenes[0].id;navigate('scenes');view='board';log('Story imported',d.title,'project');notify('Story imported as a new project');}catch{notify('Please choose a valid story JSON file');}e.target.value='';}

 function createProject(){if(!newTitle.trim())return;const id='project-'+Date.now();projects.push({id,title:newTitle.trim(),description:newDescription.trim()||'An unwritten world, full of possibility.',genre:'Story project',scenes:[{id:1,title:'Opening scene',text:'',choices:[],thread:'discovery',status:'Draft',location:''}]});projectId=id;selected=1;modal='';newTitle='';newDescription='';navigate('scenes');view='board';log('Project created',project.title,'project');notify('Your new project is ready');}

 function resizePanel(e){e.preventDefault();const start=e.clientX,width=inspectorWidth;const move=ev=>inspectorWidth=Math.max(245,Math.min(400,width+start-ev.clientX));const up=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);document.body.style.cursor='';document.body.style.userSelect='';};document.body.style.cursor='col-resize';document.body.style.userSelect='none';window.addEventListener('pointermove',move);window.addEventListener('pointerup',up);}

 function autoGrow(node){let frame,width=0;const resize=()=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{node.style.height='auto';node.style.height=`${node.scrollHeight}px`;});};const observer=new ResizeObserver(entries=>{const w=entries[0].contentRect.width;if(w!==width){width=w;resize();}});observer.observe(node);resize();return{update:resize,destroy(){observer.disconnect();cancelAnimationFrame(frame);}};}

 function trapFocus(node){const prev=document.activeElement;requestAnimationFrame(()=>{(node.querySelector('[data-autofocus]')||node).focus();});const handler=e=>{if(e.key!=='Tab')return;const items=[...node.querySelectorAll('button,input,select,textarea,a[href],[tabindex="0"]')].filter(el=>!el.disabled&&el.getClientRects().length);if(!items.length)return;if(e.shiftKey&&(document.activeElement===items[0]||document.activeElement===node)){e.preventDefault();items.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0].focus();}};node.addEventListener('keydown',handler);return{destroy(){node.removeEventListener('keydown',handler);prev?.focus();}};}

 function showContext(e,id){e.preventDefault();selected=id;context={id,x:Math.max(10,Math.min(e.clientX,window.innerWidth-205)),y:Math.min(e.clientY,window.innerHeight-170)};}

</script>



<svelte:head><title>Enchanted Quill | Story intelligence studio</title><meta name="description" content="A cinematic workspace for the worlds, characters, and stories you create."/><link rel="preconnect" href="https://fonts.googleapis.com"/><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin="anonymous"/><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;450;500;550;600;650;700;750;800&family=Space+Grotesk:wght@400;500;600;700&display=swap" rel="stylesheet"/></svelte:head>

<svelte:window onkeydown={keydown}/>

<div class="studio" class:collapsed class:focus-mode={focusMode} style:--inspector-width={`${inspectorWidth}px`}>

 <img class="world-background" src="/images/castle.jpg" alt="" fetchpriority="high"/>

 {#if mobileNav}<button class="nav-scrim" aria-label="Close navigation" onclick={()=>mobileNav=false}></button>{/if}

 <aside class="sidebar" class:mobile-open={mobileNav} aria-label="Main navigation">

  <div class="brand-row"><a class="brand" href="/" onclick={(e)=>{e.preventDefault();navigate('overview');}} aria-label="Enchanted Quill overview"><span class="brand-symbol"><Feather size={21}/></span><span class="brand-name">Enchanted Quill<span>STORY INTELLIGENCE</span></span></a><button class="icon sidebar-collapse" aria-label={collapsed?'Expand sidebar':'Collapse sidebar'} onclick={()=>collapsed=!collapsed}>{#if collapsed}<PanelLeftOpen size={16}/>{:else}<PanelLeftClose size={16}/>{/if}</button><button class="icon mobile-close" aria-label="Close navigation" onclick={()=>mobileNav=false}><X size={19}/></button></div>

  <div class="project-switcher"><span class="project-monogram">{project.title.charAt(0)}</span><div><span>Personal workspace</span><select aria-label="Switch project" value={projectId} onchange={(e)=>{projectId=e.currentTarget.value;selected=project.scenes[0]?.id;}}>{#each projects as p}<option value={p.id}>{p.title}</option>{/each}</select></div><ChevronDown size={13}/></div>

  <button class="sidebar-search" onclick={()=>{commandOpen=true;commandQuery='';}}><Search size={15}/><span>Search anything</span><kbd>⌘ K</kbd></button>

  <nav><div class="nav-group">{#each primaryNav as item}<button class="nav-item" class:active={page===item.id} onclick={()=>navigate(item.id)} title={collapsed?item.label:undefined} aria-current={page===item.id?'page':undefined}><item.icon size={17}/><span>{item.label}</span>{#if item.id==='projects'}<span class="nav-badge">{projects.length}</span>{/if}</button>{/each}</div><div class="nav-label"><span>STORY WORLD</span><span class="label-line"></span></div><div class="nav-group">{#each storyNav as item}<button class="nav-item" class:active={page===item.id} onclick={()=>navigate(item.id)} title={collapsed?item.label:undefined} aria-current={page===item.id?'page':undefined}><item.icon size={17}/><span>{item.label}</span>{#if item.id==='scenes'}<span class="nav-badge">{scenes.length}</span>{/if}</button>{/each}</div><div class="nav-label"><span>INTELLIGENCE</span><span class="label-line"></span></div><div class="nav-group">{#each intelligenceNav as item}<button class="nav-item" class:active={page===item.id} onclick={()=>navigate(item.id)} title={collapsed?item.label:undefined} aria-current={page===item.id?'page':undefined}><item.icon size={17}/><span>{item.label}</span>{#if item.id==='memory'}<span class="new-badge">BETA</span>{/if}</button>{/each}</div></nav>

  <div class="sidebar-footer"><button class="nav-item" class:active={page==='activity'} onclick={()=>navigate('activity')} title="Recent activity"><Activity size={17}/><span>Recent activity</span></button><div class="workspace-status"><span class="status-dot"></span><span>All your worlds, connected.</span><span class="mini-spark">✧</span></div><button class="account" onclick={()=>modal='guide'} title="Workspace guide"><span class="account-avatar">T</span><span><strong>The storyteller</strong><small>Personal workspace</small></span><ChevronDown size={13}/></button></div>

 </aside>

 <div class="app-shell">

  <header class="topbar"><div class="topbar-left"><button class="icon mobile-toggle" aria-label="Open navigation" onclick={()=>mobileNav=true}><Menu size={20}/></button><span class="workspace-crumb">Workspace</span><ChevronRight size={12}/><strong>{pageLabel}</strong>{#if page==='overview'}<span class="preview-label">STUDIO PREVIEW</span>{/if}</div><div class="topbar-right"><span class="save-state"><span class="status-dot" class:saving={saveStatus==='Saving changes'}></span>{saveStatus}</span><button class="icon tooltip" data-tip="Quick search · Ctrl K" aria-label="Open command palette" onclick={()=>{commandOpen=true;commandQuery='';}}><Search size={16}/></button><button class="icon tooltip" data-tip="Activity" aria-label="Notifications" aria-expanded={notificationOpen} onclick={()=>notificationOpen=!notificationOpen}><Bell size={16}/><span class="notification-dot"></span></button><button class="icon theme-toggle" aria-label={theme==='light'?'Switch to dark mode':'Switch to light mode'} title={theme==='light'?'Switch to dark mode':'Switch to light mode'} aria-pressed={theme==='dark'} onclick={()=>theme=theme==='light'?'dark':'light'}>{#if theme==='light'}<Moon size={19}/>{:else}<Sun size={19}/>{/if}</button><span class="topbar-divider"></span><button class="icon tooltip" data-tip={inspectorOpen?'Hide inspector':'Show inspector'} aria-label={inspectorOpen?'Hide inspector':'Show inspector'} onclick={()=>inspectorOpen=!inspectorOpen}>{#if inspectorOpen}<PanelRightClose size={17}/>{:else}<PanelRightOpen size={17}/>{/if}</button><button class="top-avatar" aria-label="Open workspace guide" onclick={()=>modal='guide'}>T</button></div>{#if notificationOpen}<div class="notification-popover" transition:fly={{y:-5,duration:140}}><div><strong>Workspace activity</strong><button class="icon" aria-label="Close notifications" onclick={()=>notificationOpen=false}><X size={14}/></button></div>{#each activity.slice(0,3) as a}<button onclick={()=>{navigate('activity');notificationOpen=false;}}><span class="activity-orb"><Feather size={13}/></span><span><strong>{a.title}</strong><small>{timeAgo(a.time)}</small></span></button>{/each}</div>{/if}</header>

  <div class="workspace-body"><main class="main-scroll" id="main-content">{#key page}<div class="page-content" in:fly={{y:8,duration:220}}>

   {#if page==='overview'}

    <div class="page-heading overview-heading"><div><div class="eyebrow">YOUR CREATIVE UNIVERSE</div><h1>Your story, in focus<span>.</span></h1><p>Every character. Every connection. One extraordinary world.</p></div><button class="button primary" onclick={()=>openScene(selected)}><Feather size={15}/><span>Continue writing</span><ArrowUpRight size={15}/></button></div>

    <div class="overview-tabs"><button class="selected" aria-current="page">Overview</button><button onclick={()=>navigate('activity')}>Recent activity</button><span class="tab-tail"><span class="status-dot"></span> {projects.length} active {projects.length===1?'project':'projects'}</span></div>

    <div class="metrics-grid">{#each [{label:'Projects',value:projects.length,sub:'Worlds in the making',icon:FolderOpen,page:'projects',tone:'violet'},{label:'Characters',value:characters.length,sub:'Across the story library',icon:Users,page:'characters',tone:'green'},{label:'Locations',value:locations.length,sub:'Across six story worlds',icon:MapPin,page:'locations',tone:'amber'},{label:'Scenes',value:scenes.length,sub:`${words.toLocaleString()} words written`,icon:Clapperboard,page:'scenes',tone:'blue'}] as metric}<button class="metric-card" onclick={()=>navigate(metric.page)}><span class={`metric-icon ${metric.tone}`}><metric.icon size={17}/></span><span class="metric-label">{metric.label}</span><ArrowUpRight class="metric-arrow" size={13}/><strong>{String(metric.value).padStart(2,'0')}</strong><small>{metric.sub}</small><span class="mini-bars" aria-hidden="true">{#each [4,8,5,11,9,15,13,19] as height}<i style:height={`${height}px`}></i>{/each}</span></button>{/each}</div>

    <div class="dashboard-primary"><section class="project-cover-card">{#if coverFor(project)}<img src={coverFor(project)} alt={`${project.title} cover`}/>{:else}<div class="project-art-placeholder"><Feather size={28}/><span>Story artwork pending</span></div>{/if}<div class="cover-overlay"></div><div class="cover-top"><span class="glass-pill"><span class="status-dot"></span> {project.complete?"COMPLETE STORY":"IN DEVELOPMENT"}</span><button class="icon" aria-label="Edit project details" onclick={()=>{newTitle=project.title;newDescription=project.description;modal='project-details';}}><MoreHorizontal size={18}/></button></div><div class="cover-copy"><span class="cover-genre">{project.genre} <span>·</span> Interactive narrative</span><h2>{project.title}</h2><p>{project.description}</p><div class="cover-bottom"><span><Clapperboard size={13}/>{scenes.length} scenes<span class="cover-dot">·</span><GitBranch size={13}/>{choiceCount} choices</span><button onclick={()=>{navigate('scenes');view='board';}}>Open workspace <ArrowUpRight size={16}/></button></div></div></section><section class="surface health-card"><div class="section-card-heading"><span><HeartPulse size={16}/> Narrative health</span><button class="icon" aria-label="Open narrative health" onclick={()=>navigate('health')}><ArrowUpRight size={15}/></button></div><div class="health-overview"><div class="health-ring" style:--score={`${health}%`}><span><strong>{health}<small>%</small></strong><small>CONNECTED</small></span></div><div><span class="subtle-badge green">{health===100?'Looking connected':'Room to connect'}</span><p>{health===100?'Every scene has a path.':'A few scenes are waiting for a connection.'}</p></div></div><div class="health-check"><span><Check size={13}/> {reachable.size} reachable scenes</span><span>{endings.length} endings</span></div><button class="text-button health-link" onclick={()=>navigate('health')}>Explore story structure <ArrowRight size={13}/></button></section></div>

    <div class="dashboard-secondary"><section class="surface development-card"><div class="section-card-heading"><span>Story development</span><span class="chart-perspective">Words by scene <ChevronDown size={11}/></span></div><div class="chart-summary"><strong>{words.toLocaleString()}</strong><span>words across {scenes.length} scenes</span><span class="chart-badge"><Feather size={12}/> Taking shape</span></div><ActivityChart data={scenes.slice(0,8).map(s=>countWords(s.text))} labels={scenes.slice(0,8).map((s,i)=>`SC ${String(i+1).padStart(2,'0')}`)}/></section><section class="surface relationship-card"><div class="section-card-heading"><span>Connected worlds <span class="sample-tag">SAMPLE</span></span><button class="icon" aria-label="Open relationship graph" onclick={()=>{navigate('world');view='graph';}}><ArrowUpRight size={15}/></button></div><RelationshipGraph compact on:select={(e)=>{const c=characters.find(c=>c.id===e.detail);if(c)inspect('character',c);}}/></section></div>

    <div class="section-label-row"><h2>A world beyond the page</h2><span>Make every detail matter.</span></div><div class="knowledge-grid">{#each [{title:'AI memory',icon:BrainCircuit,meta:`${notes.length} pinned notes`,text:'Keep the things your story should never forget.',page:'memory',color:'violet'},{title:'World database',icon:Database,meta:`${characters.length+locations.length} story entities`,text:'The people and places that make your world real.',page:'world',color:'green'},{title:'Prompt library',icon:WandSparkles,meta:`${prompts.length} creative prompts`,text:'A better starting point for your next question.',page:'prompts',color:'amber'}] as card}<button class="surface knowledge-card" onclick={()=>navigate(card.page)}><div><span class={`metric-icon ${card.color}`}><card.icon size={17}/></span><ArrowUpRight size={14}/></div><h3>{card.title}</h3><p>{card.text}</p><span>{card.meta}<ChevronRight size={12}/></span></button>{/each}</div>

    <section class="surface activity-preview"><div class="section-card-heading"><span>Recent activity</span><button class="text-button" onclick={()=>navigate('activity')}>View all <ArrowUpRight size={13}/></button></div>{#each activity.slice(0,3) as a}<div class="activity-row"><span class="activity-orb"><Feather size={13}/></span><div><strong>{a.title}</strong><p>{a.detail}</p></div><time>{timeAgo(a.time)}</time></div>{/each}</section>

   {:else if page==='projects'}

    <div class="page-heading"><div><div class="eyebrow">THE BIG PICTURE</div><h1>Your projects<span>.</span></h1><p>Every great story deserves a space of its own.</p></div><button class="button primary" onclick={()=>{newTitle='';newDescription='';modal='new-project';}}><Plus size={15}/> New project</button></div><div class="project-grid">{#each projects as p}<button class="project-tile surface" onclick={()=>{projectId=p.id;selected=p.scenes[0].id;navigate('overview');}}><div>{#if coverFor(p)}<img src={coverFor(p)} alt=""/>{:else}<div class="project-art-placeholder"><Feather size={28}/><span>Story artwork pending</span></div>{/if}<span class="glass-pill">{p.genre}</span></div><section><span class="project-tile-status"><span class="status-dot"></span> {p.complete?"Complete · two endings":"In development"}</span><h2>{p.title}</h2><p>{p.description}</p><footer><span>{p.scenes.length} scenes</span><span>Open project <ArrowUpRight size={14}/></span></footer></section></button>{/each}<button class="new-project-tile" onclick={()=>{newTitle='';newDescription='';modal='new-project';}}><span><Plus size={23}/></span><h3>A new world starts here</h3><p>Create your next story project.</p></button></div>

   {:else if page==='scenes'}

    <div class="page-heading workspace-heading"><div><div class="eyebrow">STORY WORKSPACE</div><h1>{project.title}</h1><p><span>{scenes.length} scenes</span><span class="dot-separator">·</span>{words.toLocaleString()} words<span class="dot-separator">·</span><span class="status-dot"></span> {project.complete?"Complete story":"Draft in progress"}</p></div><div class="heading-actions"><button class="button secondary preview-button" onclick={()=>startReading()}><Play size={14}/> Preview</button><button class="button primary" onclick={addScene}><Plus size={15}/> New scene</button></div></div>

    <div class="story-intake-toolbar"><button class="button secondary" onclick={()=>openIntake('scene')}><Upload size={15}/>Create / Import scene</button><button class="button secondary" onclick={()=>{modal='new-project';}}><BookOpen size={15}/>Import story PDF</button></div><StoryReadiness bind:project characters={storyCharacters} locations={storyLocations} {assets} onopen={openScene} onadd={openIntake} onpage={navigate}/><div class="cloud-toolbar"><button class="text-button" onclick={saveCloud}><Database size={14}/> Save cloud snapshot</button><span>{cloudStatus}</span></div><div class="media-backup-row"><span>{mediaError||'Scene images, character identities and environments are stored as separate assets.'}</span><button class="text-button" onclick={exportMedia}><Download size={14}/> Export media backup</button></div><div class="workspace-toolbar"><div class="tabs" role="tablist" aria-label="Workspace view">{#each [{id:'canvas',label:'Canvas',icon:GitBranch},{id:'board',label:'Storyboard',icon:LayoutGrid},{id:'write',label:'Scene Director',icon:AlignLeft},{id:'timeline',label:'Timeline',icon:Clock3},{id:'branches',label:'Branches',icon:GitBranch}] as item}<button role="tab" aria-selected={view===item.id} class:selected={view===item.id} onclick={()=>view=item.id}><item.icon size={14}/><span>{item.label}</span></button>{/each}</div><div class="toolbar-actions"><button class="icon tooltip" data-tip="Export story" aria-label="Export story" onclick={exportStory}><Download size={15}/></button><button class="icon tooltip" data-tip={focusMode?'Exit focus':'Focus mode'} aria-label={focusMode?'Exit focus mode':'Focus mode'} onclick={()=>focusMode=!focusMode}>{#if focusMode}<Minimize2 size={15}/>{:else}<Maximize2 size={15}/>{/if}</button></div></div>

    {#if deleted}<div class="undo-banner"><Undo2 size={14}/><span>A scene was removed.</span><button onclick={restoreScenes}>Undo</button><button class="icon" aria-label="Dismiss undo" onclick={()=>deleted=null}><X size={13}/></button></div>{/if}

    {#if view==='canvas'}{#key project.id}<StoryCanvas bind:project characters={storyCharacters} locations={storyLocations} {assets} onassetschange={refreshAssets} onnewscene={canvasNewScene} onopen={openScene} oncharacter={addCharacter} onlocation={addLocation} {notify}/>{/key}{:else if view==='board'}<div class="filter-row"><label class="search-field"><Search size={15}/><input aria-label="Search scenes" placeholder="Find a scene, a line, a moment…" bind:value={sceneQuery}/>{#if sceneQuery}<button class="icon" aria-label="Clear scene search" onclick={()=>sceneQuery=''}><X size={13}/></button>{/if}</label><label class="filter-select"><ListFilter size={14}/><select aria-label="Filter scenes" bind:value={filter}><option value="all">All scenes</option>{#each threads as t}<option value={t.id}>{t.name}</option>{/each}<option value="endings">Endings</option><option value="unlinked">Unlinked</option></select></label><span class="results-count">{shownScenes.length} scenes</span></div><div class="storyboard-grid">{#each shownScenes as s}<article class="scene-card surface" class:drag-over={dragOver===s.id} class:current={s.id===selected} draggable="true" ondragstart={(e)=>{dragId=s.id;e.dataTransfer.setData('text/plain',String(s.id));e.dataTransfer.effectAllowed='move';}} ondragover={(e)=>{e.preventDefault();dragOver=s.id;}} ondragleave={()=>dragOver=null} ondragend={()=>{dragId=null;dragOver=null;}} ondrop={(e)=>{e.preventDefault();if(dragId!==null)reorder(dragId,s.id);dragId=null;dragOver=null;}} oncontextmenu={(e)=>showContext(e,s.id)} aria-label={`Scene ${s.id}: ${s.title}`}><button class="scene-card-image" onclick={()=>openScene(s.id)}><!-- scene asset only -->{#if sceneVisual(s)}<img src={sceneVisual(s)} alt={`Approved image for ${s.title}`}/>{:else}<span class="board-image-pending"><Clapperboard size={27}/><span>Scene image pending</span></span>{/if}<span class="scene-slug">SCENE {String(s.id).padStart(2,'0')}</span><span class="scene-play"><Play size={17}/></span></button><div class="scene-card-copy"><div class="scene-card-meta"><span class="thread-label" style:--thread-color={threadFor(s).color}><i></i>{threadFor(s).name}</span><button class="icon" aria-label={`Scene ${s.id} options`} onclick={(e)=>showContext(e,s.id)}><MoreHorizontal size={17}/></button></div><button class="scene-name" onclick={()=>openScene(s.id)}>{s.title}</button><p>{s.text?s.text.slice(0,95)+(s.text.length>95?'…':''):'A blank page. An open possibility.'}</p><div class="scene-card-footer"><span><MapPin size={11}/>{s.location||'Set a location'}</span><span>{s.choices.length} <GitBranch size={11}/></span></div></div><div class="scene-card-status"><span class:in-progress={s.status==='In progress'}><i></i>{s.status||'Draft'}</span><span>{countWords(s.text)} words</span></div></article>{/each}<button class="new-scene-card" onclick={addScene}><span><Plus size={22}/></span><h3>The next moment</h3><p>Add a scene to your story.</p></button>{#if !shownScenes.length}<div class="empty-state"><Search size={28}/><h3>No scenes found</h3><p>Try another search or choose a different thread.</p><button class="button secondary" onclick={()=>{sceneQuery='';filter='all';}}>Clear filters</button></div>{/if}</div>

    {:else if view==='write'}<div class="writing-layout"><div class="scene-strip"><div><span>SCENES</span><button class="icon" aria-label="Add scene" onclick={addScene}><Plus size={14}/></button></div><select class="mobile-scene-select" aria-label="Select scene" value={selected} onchange={(e)=>openScene(Number(e.currentTarget.value))}>{#each scenes as s}<option value={s.id}>{String(s.id).padStart(2,'0')} · {s.title}</option>{/each}</select><div class="strip-list">{#each scenes as s}<button class:selected={s.id===selected} onclick={()=>{selected=s.id;selectedEntity=null;}}><span>{String(s.id).padStart(2,'0')}</span><span>{s.title}</span><i style:background={threadFor(s).color}></i></button>{/each}</div></div><section class="writing-canvas surface"><div class="writing-topline"><span class="thread-label" style:--thread-color={threadFor(scene).color}><i></i>{threadFor(scene).name}</span><div><span class="font-size">{fontSize}px</span><button class="icon" aria-label="Decrease text size" disabled={fontSize<=14} onclick={()=>fontSize--}>A−</button><button class="icon" aria-label="Increase text size" disabled={fontSize>=23} onclick={()=>fontSize++}>A+</button><button class="icon" aria-label="Duplicate scene" onclick={()=>duplicateScene()}><Copy size={14}/></button></div></div><div class="script-page"><span class="script-scene-label">SCENE {String(scene.id).padStart(2,'0')}</span><input class="scene-title-input" aria-label="Scene title" placeholder="Give this moment a name" bind:value={scene.title} onblur={()=>log('Scene title edited',scene.title)}/></div>{#key project.id+':'+scene.id}<SceneDirector bind:scene storyId={project.id} characters={storyCharacters} locations={storyLocations} {assets} previous={scenes[scenes.findIndex(s=>s.id===scene.id)-1]} onassetschange={refreshAssets} onlocation={addLocation} onnext={connectNew} {notify}/>{/key}<div class="branch-editor"><div class="section-card-heading"><span><GitBranch size={15}/> Reader choices</span><button class="text-button" onclick={addChoice}><Plus size={13}/> Add choice</button></div>{#each scene.choices as choice,i}<div class="choice-editor-row"><span class="choice-number">{i+1}</span><div><input aria-label={`Choice ${i+1} text`} bind:value={choice.label}/><label>Leads to<select aria-label={`Choice ${i+1} destination`} bind:value={choice.target}>{#each scenes as s}<option value={s.id}>{String(s.id).padStart(2,'0')} · {s.title}</option>{/each}</select></label></div><button class="icon" aria-label={`Open choice ${i+1} destination`} onclick={()=>openScene(choice.target)}><ArrowUpRight size={15}/></button><button class="icon" aria-label={`Remove choice ${i+1}`} onclick={()=>scene.choices.splice(i,1)}><X size={13}/></button></div>{/each}{#if !scene.choices.length}<div class="ending-message"><Flag size={15}/><span>This scene is an ending. Add a choice to continue the journey.</span></div>{/if}<button class="connect-new" onclick={connectNew}><Plus size={13}/> Create and connect a new scene <ArrowUpRight size={13}/></button></div></section></div>

    {:else if view==='timeline'}<section class="surface timeline-surface"><div class="view-intro"><div><h2>One story. Many moving parts.</h2><p>Follow each thread through the order of your scenes.</p></div><span class="sample-tag">DRAG TO REORDER</span></div><div class="thread-legend">{#each threads as t}<span><i style:background={t.color}></i>{t.name}</span>{/each}</div><Timeline {scenes} {selected} on:select={(e)=>openScene(e.detail)} on:reorder={(e)=>reorder(e.detail.from,e.detail.to)}/></section>

    {:else if view==='branches'}<section class="surface branches-surface"><div class="view-intro"><div><h2>A choice changes the shape of everything.</h2><p>Every connection below comes from your story.</p></div><span class="subtle-badge">{choiceCount} connections</span></div><div class="branch-grid">{#each scenes as s}<article class="branch-node"><button onclick={()=>openScene(s.id)}><span>SCENE {String(s.id).padStart(2,'0')}{s.id===scenes[0].id?' · START':''}</span><h3>{s.title}</h3></button>{#each s.choices as c}<button class="branch-connection" onclick={()=>openScene(c.target)}><GitBranch size={13}/><span>{c.label}</span><span>{String(c.target).padStart(2,'0')}<ArrowUpRight size={12}/></span></button>{/each}{#if !s.choices.length}<span class="branch-ending"><Flag size={12}/><span>Story ending</span></span>{/if}</article>{/each}</div></section>{/if}

   {:else if page==='generation'}<div class="page-heading"><div><div class="eyebrow">FROM IDEA TO FRAME</div><h1>Generation studio.</h1><p>Configure a mock workflow for the selected story and scene. Live generation remains locked.</p></div></div><label class="director-field">Scene<select bind:value={selected}>{#each scenes as s}<option value={s.id}>{s.title}</option>{/each}</select></label><label class="director-field">Generation capability<select bind:value={generationType}><option value="scene">Storyboard scene</option><option value="text-to-image">Text to image</option><option value="image-to-video">Image to video</option><option value="text-to-video">Text to video</option></select></label>{#key project.id+':'+selected+':'+generationType}<GenerationStudio storyId={project.id} {scene} kind={generationType} prompt={generationType==='image-to-video'?currentPrompts.imageToVideo:generationType==='text-to-video'?currentPrompts.textToVideo:currentPrompts.image} {assets} onassetschange={refreshAssets} {notify}/>{/key}

   {:else if page==='credits'||page==='provider'}{#key page}<ProviderPanel admin={page==='provider'}/>{/key}

   {:else if page==='cloud'}<div class="page-heading"><div><div class="eyebrow">PERSISTENT STORY SPACES</div><h1>Pick up where you left off.</h1><p>Reopen saved cloud projects with their characters, locations, scenes and canvas connections. Your existing local version is preserved as a backup.</p></div><button class="button secondary" onclick={loadCloud}>Refresh cloud projects</button></div>{#if localBackups.length}<section class="surface provider-audit"><h2>Previous local versions</h2>{#each localBackups.toReversed() as backup}<div><span>{backup.project.title} · {new Date(backup.savedAt).toLocaleString()}</span><button class="button secondary" onclick={()=>restoreCloud({id:backup.project.id,revision:backup.project.cloudRevision||null,payload:JSON.stringify(backup.project)})}>Restore local version</button></div>{/each}</section>{/if}<p class="workspace-account-id">Workspace account: {userSession?.user?.id||'Sign in required'}</p><div class="project-grid">{#each cloudProjects as record}<article class="surface plan-card"><h2>{JSON.parse(record.payload).title}</h2><p>Revision {record.revision} · {new Date(record.updated).toLocaleString()}</p><button class="button primary" onclick={()=>restoreCloud(record)}>Reopen story space <ArrowRight size={14}/></button></article>{/each}{#if !cloudProjects.length}<div class="empty-state"><Database size={30}/><h3>No cloud snapshots yet.</h3><p>Save a snapshot from your Story Workspace to reopen it on another device.</p></div>{/if}</div>

   {:else if page==='characters'}

    <div class="page-heading"><div><div class="eyebrow">THE PEOPLE IN YOUR WORLD</div><h1>More than a name<span>.</span></h1><p>Identity, intention, and every angle in between.</p></div><span class="subtle-badge"><Users size={13}/>{storyCharacters.length} story characters</span></div><div class="info-banner"><Sparkles size={15}/><span>Characters belong to this story. Import portraits and reference sheets or develop a new identity here.</span></div><div class="asset-library-actions"><button class="button primary" onclick={()=>openIntake('character')}><Plus size={15}/>Add character</button><span>Create / Generate or import your own reference.</span></div><div class="character-grid">{#each storyCharacters as c}<article class="character-card surface"><div class="character-header"><button class="character-portrait" onclick={()=>inspect('character',c)} aria-label={`Inspect ${c.name}`}>{#if characterVisual(c)}<img src={characterVisual(c)} alt={`Visual reference for ${c.name}`} loading="lazy"/>{:else}<span class="character-initials">{c.name.split(" ").map(n=>n[0]).join("").slice(0,2)}</span>{/if}</button><div><span class="character-role" style:color={c.color}>{c.role}</span><h2>{c.name}</h2><p>{c.archetype}</p><span class="character-project-name">{c.projectTitle}</span></div><button class="icon" aria-label={`Open ${c.name} inspector`} onclick={()=>inspect('character',c)}><ArrowUpRight size={17}/></button></div><p class="character-description">{c.description}</p><ReferenceAssets entity={c} type="character" storyId={project.id} {assets} onassetschange={refreshAssets} {notify}/>{#if c.referenceReady}<button class="turnaround-preview" onclick={()=>showSheet(c)} aria-label={`View ${c.name} full-body reference sheet`}><img src={c.referenceSheet||`/images/${c.id}-turnaround.png`} alt={`${c.name} full-body character turnaround showing front, profile, three-quarter, and back views in futuristic fantasy clothing`} loading="lazy"/><span class="image-expand"><Maximize2 size={15}/> View reference sheet</span></button><div class="sheet-angle-labels"><span>FRONT</span><span>PROFILE</span><span>THREE-QUARTER</span><span>BACK</span></div>{:else}<div class="character-design-brief"><span>CHARACTER DOSSIER</span><h3>What they want</h3><p>{c.desire||'Add a motivation as you develop this profile.'}</p><h3>What stands in their way</h3><p>{c.conflict||'Define the obstacle this character faces.'}</p><span class="subtle-badge">{characterVisual(c)?'Full reference sheet not verified':'Visual reference not generated'}</span></div>{/if}<div class="character-detail-tags"><span>{c.age?c.age+' years old':'Age not specified'}</span><span>{c.referenceReady?"Photographic reference":"Detailed design brief"}</span><span>{c.role}</span></div><details class="prompt-details"><summary><WandSparkles size={14}/><span>Generation prompts</span><ChevronDown size={14}/></summary><div><h4>{c.referenceReady?"Turnaround sheet":"Character visual brief"}</h4><p>{c.referencePrompt||turnaroundPrompts.find(p=>p.key===c.id)?.prompt||c.prompt}</p><button class="text-button" onclick={()=>copyText(c.referencePrompt||turnaroundPrompts.find(p=>p.key===c.id)?.prompt||c.prompt)}><Copy size={12}/> Copy sheet prompt</button><h4>{c.referenceReady?"Portrait identity reference":"Identity and costume direction"}</h4><p>{c.prompt}</p><button class="text-button" onclick={()=>copyText(c.prompt)}><Copy size={12}/> Copy portrait prompt</button></div></details></article>{/each}</div>

   {:else if page==='locations'}

    <div class="page-heading"><div><div class="eyebrow">THE WORLD AROUND THE STORY</div><h1>Places with a presence<span>.</span></h1><p>Build settings your audience can almost step into.</p></div><span class="subtle-badge">{storyLocations.length} story locations</span></div><div class="asset-library-actions"><button class="button primary" onclick={()=>openIntake('location')}><Plus size={15}/>Add location</button><span>Each location keeps its own environment reference.</span></div><div class="locations-grid">{#each storyLocations as location}<article class="location-card surface"><button onclick={()=>inspect('location',location)}>{#if locationVisual(location)}<img src={locationVisual(location)} alt={location.name} loading="lazy"/>{:else}<span class="location-reference-pending"><MapPin size={28}/><strong>{location.name}</strong><small>Unique reference pending</small></span>{/if}<span class="location-type"><MapPin size={12}/>{location.type}</span><span class="image-expand"><ArrowUpRight size={17}/></span></button><div><span class="location-detail">{location.detail}</span><span class="location-project-name">{location.projectTitle}</span><h2>{location.name}</h2><p>{location.description}</p><ReferenceAssets entity={location} type="location" storyId={project.id} {assets} onassetschange={refreshAssets} {notify}/><footer><span>{location.atmosphere}</span><button class="icon" aria-label={`Inspect ${location.name}`} onclick={()=>inspect('location',location)}><ArrowUpRight size={16}/></button></footer></div></article>{/each}</div>

   {:else if page==='themes'}

    <div class="page-heading"><div><div class="eyebrow">WHAT THE STORY IS REALLY ABOUT</div><h1>The threads beneath<span>.</span></h1><p>Develop the ideas that shape this story and connect them to its scenes.</p></div><span class="sample-tag">SAMPLE STORY CONTEXT</span></div><div class="asset-library-actions"><button class="button primary" onclick={()=>openIntake('theme')}><Plus size={15}/>Add theme</button><span>Create a theme or import a moodboard and its description.</span></div>{#if project.themes?.length}<div class="themes-grid">{#each project.themes as t}<section class="surface theme-card"><h2>{t.name}</h2><p>{t.description}</p>{#if assets.find(a=>a.id===t.referenceAssetId)}<img class="import-preview" src={assets.find(a=>a.id===t.referenceAssetId).url} alt={t.name}/>{/if}<label class="director-field">Description<textarea bind:value={t.description}></textarea></label><p>{t.sceneIds?.length||0} connected scenes</p><div class="import-cast">{#each scenes as sc}<label><input type="checkbox" checked={t.sceneIds?.includes(sc.id)} onchange={()=>t.sceneIds=t.sceneIds?.includes(sc.id)?t.sceneIds.filter(id=>id!==sc.id):[...(t.sceneIds||[]),sc.id]}/>{sc.title}</label>{/each}</div></section>{/each}</div>{/if}<details class="theme-templates"><summary>Explore reusable theme templates</summary><div class="themes-grid">{#each themes as theme,i}<section class="surface theme-card" style:--theme-color={theme.color}><span class="theme-index">0{i+1}</span><div class="theme-orbit"><Layers3 size={27}/></div><h2>{theme.name}</h2><p>{theme.description}</p><div class="theme-appearances"><span>EXPLORE IN SCENES</span>{#each theme.scenes.filter(id=>scenes.some(s=>s.id===id)) as id}<button onclick={()=>openScene(id)}><span>SC {String(id).padStart(2,'0')}</span>{scenes.find(s=>s.id===id).title}<ArrowUpRight size={13}/></button>{/each}</div></section>{/each}</div></details><section class="surface threads-panel"><div class="section-card-heading"><span>Narrative threads</span><button class="text-button" onclick={()=>{navigate('scenes');view='timeline';}}>Open timeline <ArrowUpRight size={13}/></button></div>{#each threads as t}<div class="thread-row"><i style:background={t.color}></i><div><strong>{t.name}</strong><p>{t.description}</p></div><span>{scenes.filter(s=>(s.thread||'discovery')===t.id).length} scenes</span></div>{/each}</section>

   {:else if page==='memory'}

    <div class="page-heading"><div><div class="eyebrow">CONTEXT THAT STAYS WITH YOU</div><h1>A story worth remembering<span>.</span></h1><p>Your creative direction, gathered in one quiet place.</p></div><button class="button primary" onclick={()=>{newTitle='';newDescription='';modal='new-note';}}><Plus size={15}/> Pin a note</button></div><div class="info-banner"><BrainCircuit size={15}/><span>Design preview. These are editable, pinned context notes; live AI retrieval is not connected.</span></div><div class="memory-layout"><div class="memory-notes">{#each notes as note}<details class="surface memory-note" open><summary><span class="memory-icon"><Pin size={15}/></span><div><span>{note.type}</span><h3>{note.title}</h3></div><ChevronDown size={15}/></summary><div class="memory-note-body"><textarea aria-label={`${note.title} note`} bind:value={note.text} onblur={()=>log('Context note edited',note.title,'memory')}></textarea><span><ShieldCheck size={12}/> Pinned by you</span></div></details>{/each}</div><section class="surface memory-explainer"><span class="large-icon violet"><BrainCircuit size={28}/></span><h2>Keep the context.<br/>Stay in the story.</h2><p>A place for the rules, truths, and intentions that should carry across every scene.</p><div><Check size={14}/> World rules and continuity</div><div><Check size={14}/> Character motivations</div><div><Check size={14}/> Creative decisions</div></section></div>

   {:else if page==='world'}

    <div class="page-heading"><div><div class="eyebrow">ONE CONNECTED UNIVERSE</div><h1>The world behind the words<span>.</span></h1><p>Understand the relationships that hold everything together.</p></div><span class="sample-tag">SAMPLE KNOWLEDGE</span></div><div class="workspace-toolbar"><div class="tabs" role="tablist" aria-label="World database view"><button role="tab" class:selected={view!=='entities'} aria-selected={view!=='entities'} onclick={()=>view='graph'}><GitBranch size={14}/> Relationships</button><button role="tab" class:selected={view==='entities'} aria-selected={view==='entities'} onclick={()=>view='entities'}><ListFilter size={14}/> All entities</button></div><span class="results-count">{characters.length+locations.length} entities</span></div>{#if view==='entities'}<section class="surface entity-table"><div class="entity-table-head"><span>Entity</span><span>Type</span><span>Context</span><span></span></div>{#each [...characters.map(c=>({...c,entityType:'Character',context:c.role})),...locations.map(l=>({...l,entityType:'Location',context:l.type}))] as entity}<button onclick={()=>inspect(entity.entityType.toLowerCase(),entity)}><span>{#if entity.image}<img src={entity.image} alt=""/>{:else}<span class="entity-initials">{entity.name.split(" ").map(n=>n[0]).join("").slice(0,2)}</span>{/if}{entity.name}</span><span>{entity.entityType}</span><span>{entity.context}</span><ArrowUpRight size={14}/></button>{/each}</section>{:else}<section class="surface world-graph-panel"><div class="section-card-heading"><span><GitBranch size={15}/> Relationship graph</span><span class="subtle-badge">Select a connection</span></div><RelationshipGraph on:select={(e)=>{const c=characters.find(c=>c.id===e.detail);if(c)inspect('character',c);else if(e.detail==='castle')inspect('location',locations[0]);else inspect('note',notes[0]);}}/><div class="graph-footer"><span><i style:background={characters[0].color}></i> Characters</span><span><i style:background="#8f9fae"></i> Locations</span><span><i style:background="#a9b68c"></i> Story elements</span><span>Sample relationships</span></div></section>{/if}

   {:else if page==='health'}

    <div class="page-heading"><div><div class="eyebrow">A CLEARER VIEW OF THE STORY</div><h1>Follow every loose thread<span>.</span></h1><p>Simple structural checks, grounded in your actual scenes.</p></div><button class="button secondary" onclick={()=>{navigate('scenes');view='branches';}}><GitBranch size={14}/> View branches</button></div><div class="health-detail-grid"><section class="surface health-detail-score"><div class="health-ring large" style:--score={`${health}%`}><span><strong>{health}<small>%</small></strong><small>CONNECTED</small></span></div><h2>{health===100?'Your scenes are connected.':'Some scenes need a way in.'}</h2><p>{reachable.size} of {scenes.length} scenes can be reached from the opening.</p><span class="sample-tag">STRUCTURAL CHECK · NOT AN AI QUALITY SCORE</span></section><section class="surface health-checks"><h2>Story structure</h2>{#each [{label:'Scene reachability',detail:`${scenes.length-reachable.size} unlinked scenes`,good:health===100},{label:'Reader choices',detail:`${choiceCount} choices across your story`,good:choiceCount>0},{label:'Story endings',detail:`${endings.length} endings to discover`,good:endings.length>0},{label:'Scene content',detail:`${scenes.filter(s=>!s.text.trim()).length} blank scenes`,good:scenes.every(s=>s.text.trim())}] as item}<div class="health-check-row"><span class:warning={!item.good}>{#if item.good}<Check size={15}/>{:else}<Circle size={14}/>{/if}</span><div><h3>{item.label}</h3><p>{item.detail}</p></div><span class="subtle-badge" class:amber={!item.good}>{item.good?'Ready':'Review'}</span></div>{/each}</section></div><section class="surface health-scenes"><div class="section-card-heading"><span>Scenes to review</span><span>{scenes.filter(s=>!reachable.has(s.id)||!s.text.trim()).length} suggestions</span></div>{#each scenes.filter(s=>!reachable.has(s.id)||!s.text.trim()) as s}<button onclick={()=>openScene(s.id)}><span class="activity-orb"><Clapperboard size={15}/></span><div><strong>{s.title}</strong><p>{!reachable.has(s.id)?'Add a choice that leads to this scene.':'Give this scene its first words.'}</p></div><ArrowUpRight size={16}/></button>{:else}<div class="empty-state compact-empty"><ShieldCheck size={29}/><h3>No loose ends here.</h3><p>All scenes are reachable and contain writing.</p></div>{/each}</section>

   {:else if page==='prompts'}

    <div class="page-heading"><div><div class="eyebrow">BETTER QUESTIONS. DEEPER STORIES.</div><h1>A spark for the next draft<span>.</span></h1><p>Thoughtful starting points for your creative process.</p></div><span class="subtle-badge"><WandSparkles size={13}/>{prompts.length} curated prompts</span></div><div class="prompt-library-grid">{#each prompts as prompt,i}<article class="surface prompt-library-card"><div><span class={`metric-icon ${['violet','green','amber','blue'][i]}`}><WandSparkles size={18}/></span><span class="subtle-badge">{prompt.category}</span></div><h2>{prompt.title}</h2><p class="prompt-summary">{prompt.summary}</p><details class="full-prompt"><summary>Read the full prompt <ChevronDown size={15}/></summary><p>{prompt.text}</p></details><button class="button secondary" onclick={()=>copyText(prompt.text)}><Copy size={13}/> Copy prompt <ArrowUpRight size={13}/></button></article>{/each}</div><div class="quiet-note"><Sparkles size={14}/><span>Copy a prompt into your preferred AI tool. Live AI generation is not connected in this design preview.</span></div>

   {:else if page==='activity'}

    <div class="page-heading"><div><div class="eyebrow">THE STORY OF YOUR STORY</div><h1>Every little step forward<span>.</span></h1><p>Recent edits and creative decisions in this workspace.</p></div><span class="subtle-badge"><Activity size={13}/> On this device</span></div><section class="surface activity-feed"><div class="section-card-heading"><span>Workspace activity</span><span>{activity.length} events</span></div>{#each activity as a}<div class="activity-row"><span class="activity-orb">{#if a.type==='memory'}<BrainCircuit size={15}/>{:else if a.type==='project'}<FolderOpen size={15}/>{:else}<Feather size={15}/>{/if}</span><div><strong>{a.title}</strong><p>{a.detail}</p></div><time>{timeAgo(a.time)}</time></div>{/each}</section>

   {/if}

   <footer class="page-footer"><span>Enchanted Quill <span>·</span> A little intelligence. A world of possibility.</span><button onclick={()=>modal='guide'}><Keyboard size={13}/> Shortcuts & guide</button></footer>

  </div>{/key}</main>

  {#if inspectorOpen&&!focusMode}{#if compact}<button class="inspector-scrim" aria-label="Close inspector" onclick={()=>inspectorOpen=false}></button>{/if}<button class="panel-resizer" role="slider" aria-label="Resize inspector" aria-orientation="vertical" aria-valuemin="245" aria-valuemax="400" aria-valuenow={inspectorWidth} tabindex="0" onpointerdown={resizePanel} onkeydown={(e)=>{if(e.key==='ArrowLeft')inspectorWidth=Math.min(400,inspectorWidth+15);if(e.key==='ArrowRight')inspectorWidth=Math.max(245,inspectorWidth-15);}}></button><aside class="inspector" in:fly={{x:12,duration:180}}><div class="inspector-title"><span><Sparkles size={14}/>{selectedEntity?'Entity inspector':'Story context'}</span><button class="icon" aria-label="Close inspector" onclick={()=>inspectorOpen=false}><PanelRightClose size={15}/></button></div><div class="inspector-tabs"><button class:selected={inspectorTab==='details'} onclick={()=>inspectorTab='details'}>Details</button><button class:selected={inspectorTab==='knowledge'} onclick={()=>inspectorTab='knowledge'}>Knowledge</button></div><div class="inspector-scroll">

   {#if inspectorTab==='knowledge'}<div class="inspector-intro"><span class="large-icon violet"><BrainCircuit size={24}/></span><h2>A world with context.</h2><p>The rules and intentions behind the writing.</p></div>{#each notes as note}<details class="knowledge-accordion" open><summary><Pin size={12}/><span>{note.title}</span><ChevronDown size={12}/></summary><p>{note.text}</p></details>{/each}<button class="inspector-link" onclick={()=>navigate('memory')}>Open AI memory <ArrowUpRight size={13}/></button>

   {:else if selectedEntity?.type==='character'}{@const c=selectedEntity.item}<div class="inspector-character">{#if characterVisual(c)}<img src={characterVisual(c)} alt={c.name}/>{:else}<span class="character-initials large-initials">{c.name.split(" ").map(n=>n[0]).join("").slice(0,2)}</span>{/if}<span class="subtle-badge">{c.role}</span><h2>{c.name}</h2><p>{c.description}</p></div><details class="knowledge-accordion" open><summary><Target size={13}/><span>Motivation</span><ChevronDown size={12}/></summary><p>{c.desire||'Add a motivation as you develop this profile.'}</p></details><details class="knowledge-accordion" open><summary><Layers3 size={13}/><span>Inner conflict</span><ChevronDown size={12}/></summary><p>{c.conflict||'Define the obstacle this character faces.'}</p></details>{#if c.referenceReady}<button class="inspector-sheet" onclick={()=>showSheet(c)}><img src={c.referenceSheet||`/images/${c.id}-turnaround.png`} alt={`${c.name} reference sheet`}/><span><Maximize2 size={12}/> Full-body reference sheet</span></button>{/if}<span class="inspector-footnote">{c.projectTitle} · Fictional character</span><button class="inspector-link" onclick={()=>selectedEntity=null}>Back to story context <ArrowRight size={13}/></button>

   {:else if selectedEntity?.type==='location'}{@const location=selectedEntity.item}<div class="inspector-location">{#if locationVisual(location)}<img src={locationVisual(location)} alt={location.name}/>{/if}<span class="eyebrow">{location.type}</span><h2>{location.name}</h2><p>{location.description}</p><span>{location.detail}</span></div><details class="knowledge-accordion" open><summary><Eye size={13}/><span>Atmosphere</span><ChevronDown size={12}/></summary><p>{location.atmosphere}</p></details><button class="inspector-link" onclick={()=>selectedEntity=null}>Back to story context <ArrowRight size={13}/></button>

   {:else if page==='scenes'}<div class="inspector-scene-heading"><span class="eyebrow">SCENE {String(scene.id).padStart(2,'0')}</span><h2>{scene.title}</h2><p>{countWords(scene.text)} words <span>·</span> {scene.choices.length} choices</p></div><div class="inspector-fields"><label>Status<select value={scene.status} onchange={e=>{const value=e.currentTarget.value;const error=value==='Ready for review'?validateScene(scene):'';if(error){notify(error);e.currentTarget.value=scene.status;return;}scene.status=value;scene.finalized=value==='Ready for review';}}><option>Draft</option><option>In progress</option><option>Ready for review</option></select></label><label>Narrative thread<select bind:value={scene.thread}>{#each threads as t}<option value={t.id}>{t.name}</option>{/each}</select></label><label>Location<select value={scene.location} onchange={e=>{scene.location=e.currentTarget.value;scene.locationId=locations.find(l=>l.name===scene.location)?.id||'';}}><option value="">Not set</option>{#each locations as l}<option value={l.name}>{l.name}</option>{/each}<option>The Old Quarter</option></select></label></div><details class="knowledge-accordion" open><summary><Users size={13}/><span>Character context</span><ChevronDown size={12}/></summary><p class="small-disclosure">Characters selected for this scene.</p>{#each characters.filter(c=>scene.characterIds?.includes(c.id)) as c}<button class="inspector-person" onclick={()=>inspect('character',c)}>{#if characterVisual(c)}<img src={characterVisual(c)} alt=""/>{:else}<span class="entity-initials">{c.name.split(" ").map(n=>n[0]).join("").slice(0,2)}</span>{/if}<span>{c.name}<small>{c.role}</small></span><ArrowUpRight size={12}/></button>{/each}</details><details class="knowledge-accordion"><summary><BrainCircuit size={13}/><span>Continuity notes</span><ChevronDown size={12}/></summary><p>{notes[0]?.text}</p></details><button class="inspector-link" onclick={()=>startReading(selected)}><Play size={13}/> Preview this scene <ArrowUpRight size={13}/></button>

   {:else}<div class="inspector-project-cover">{#if coverFor(project)}<img src={coverFor(project)} alt=""/>{/if}<span>THE WORLD YOU'RE BUILDING</span></div><div class="inspector-project-copy"><span class="subtle-badge">{project.genre}</span><h2>{project.title}</h2><p>{project.description}</p></div><details class="knowledge-accordion" open><summary><BookOpen size={13}/><span>At a glance</span><ChevronDown size={12}/></summary><dl><div><dt>Format</dt><dd>Interactive story</dd></div><div><dt>Stage</dt><dd>{project.complete?"Complete":"Development"}</dd></div><div><dt>Scenes</dt><dd>{scenes.length}</dd></div><div><dt>Reading paths</dt><dd>{endings.length} endings</dd></div></dl></details><details class="knowledge-accordion" open><summary><Layers3 size={13}/><span>Narrative threads</span><ChevronDown size={12}/></summary>{#each threads as t}<button class="inspector-thread" onclick={()=>{navigate('scenes');view='timeline';}}><i style:background={t.color}></i><span>{t.name}</span><span>{scenes.filter(s=>(s.thread||'discovery')===t.id).length}</span></button>{/each}</details><details class="knowledge-accordion"><summary><Users size={13}/><span>The people in this world</span><ChevronDown size={12}/></summary>{#each storyCharacters as c}<button class="inspector-person" onclick={()=>inspect('character',c)}>{#if characterVisual(c)}<img src={characterVisual(c)} alt=""/>{:else}<span class="entity-initials">{c.name.split(" ").map(n=>n[0]).join("").slice(0,2)}</span>{/if}<span>{c.name}<small>{c.role}</small></span><ArrowUpRight size={12}/></button>{/each}</details><div class="inspector-note"><Sparkles size={16}/><div><strong>Every detail belongs.</strong><p>Explore your characters, follow a thread, or return to the page.</p></div></div>{/if}

  </div><div class="inspector-bottom"><span class="status-dot"></span> A quiet place to build something extraordinary.</div></aside>{/if}

  </div>

 </div>

 <nav class="mobile-dock" aria-label="Mobile workspace navigation"><button class:active={page==='overview'} onclick={()=>navigate('overview')}><LayoutDashboard size={19}/><span>Overview</span></button><button class:active={page==='scenes'} onclick={()=>{navigate('scenes');view='board';}}><Clapperboard size={19}/><span>Workspace</span></button><button class="dock-create" aria-label="Create scene" onclick={addScene}><Plus size={22}/></button><button class:active={page==='characters'} onclick={()=>navigate('characters')}><Users size={19}/><span>Characters</span></button><button onclick={()=>{commandOpen=true;commandQuery='';}}><Search size={19}/><span>Search</span></button></nav>

</div>

{#if toast}<div class="toast" role="status" transition:fly={{y:12,duration:180}}><span><Check size={15}/></span>{toast}</div>{/if}

{#if context}<button class="context-scrim" aria-label="Close scene options" onclick={()=>context=null}></button><div class="context-menu" style:left={`${context.x}px`} style:top={`${context.y}px`} transition:fade={{duration:100}}><span>SCENE {String(context.id).padStart(2,'0')}</span><button onclick={()=>openScene(context.id)}><Feather size={14}/> Edit scene</button><button onclick={()=>{duplicateScene(context.id);context=null;}}><Copy size={14}/> Duplicate</button><button onclick={()=>{startReading(context.id);context=null;}}><Play size={14}/> Preview scene</button><button class="danger" onclick={()=>deleteScene(context.id)}><Trash2 size={14}/> Remove scene</button></div>{/if}

{#if commandOpen}<div class="modal-backdrop command-backdrop"><div class="command-palette" role="dialog" aria-modal="true" aria-label="Quick command palette" tabindex="-1" use:trapFocus in:fly={{y:-12,duration:160}}><div class="command-input"><Search size={20}/><input data-autofocus aria-label="Search commands and scenes" placeholder="Where would you like to go?" bind:value={commandQuery} onkeydown={(e)=>{if(e.key==='Enter'&&commands.length)runCommand(commands[0]);}}/><button onclick={()=>commandOpen=false} aria-label="Close command palette"><kbd>esc</kbd></button></div><div class="command-results">{#each commands as c,i}{#if i===0||commands[i-1].group!==c.group}<span class="command-group">{c.group}</span>{/if}<button onclick={()=>runCommand(c)}><c.icon size={16}/><span>{c.label}</span><ArrowUpRight size={13}/></button>{:else}<div class="command-empty"><Search size={25}/><p>No matches. Try a scene name or a workspace view.</p></div>{/each}</div><div class="command-footer"><span><Command size={12}/> ENCHANTED QUILL</span><span>Tab to explore <kbd>↵</kbd> to open</span></div></div></div>{/if}

{#if playing}<div class="modal-backdrop"><div class="reader-modal" role="dialog" aria-modal="true" aria-label="Story preview" tabindex="-1" use:trapFocus in:fly={{y:12,duration:180}}><div class="modal-top"><span><BookOpen size={17}/>{project.title}</span><button class="icon" aria-label="Close preview" onclick={()=>playing=false}><X size={19}/></button></div><div class="reader-content"><div class="reader-eyebrow"><span>SCENE {String(playScene.id).padStart(2,'0')}</span><span>{history.length+1} {history.length===0?'page':'pages'} explored</span></div><h2>{playScene.title}</h2><div class="reader-prose">{playScene.text||'This scene is waiting for its first words.'}</div><div class="reader-options">{#each playScene.choices as c,i}<button onclick={()=>turnPage(c.target)}><span>{String(i+1).padStart(2,'0')}</span><strong>{c.label}</strong><ChevronRight size={17}/></button>{/each}{#if !playScene.choices.length}<div class="reader-ending"><Flag size={20}/><span>Every ending leaves a possibility.</span></div><button onclick={()=>{history=[];playId=scenes[0].id;}}><BookOpen size={16}/><strong>Explore another path</strong><ArrowRight size={16}/></button>{/if}</div><div class="reader-nav">{#if history.length}<button class="text-button" onclick={()=>playId=history.pop()}><ArrowRight class="rotate-arrow" size={13}/> Previous page</button>{/if}<button class="text-button" onclick={()=>{openScene(playId);playing=false;}}>Edit this scene <Feather size={13}/></button></div></div></div></div>{/if}

{#if sheetCharacter}<div class="modal-backdrop sheet-backdrop"><div class="sheet-modal" role="dialog" aria-modal="true" aria-label={`${sheetCharacter.name} reference sheet`} tabindex="-1" use:trapFocus in:fly={{y:8,duration:180}}><div class="modal-top"><div><span class="sheet-title">{sheetCharacter.name}</span><span class="sheet-subtitle">Character reference · Futuristic fantasy</span></div><div class="sheet-actions"><button class="icon" aria-label={sheetZoom?'Fit reference sheet':'Enlarge reference sheet'} onclick={()=>sheetZoom=!sheetZoom}>{#if sheetZoom}<ZoomOut size={18}/>{:else}<ZoomIn size={18}/>{/if}</button><a class="icon" href={sheetCharacter.referenceSheet||`/images/${sheetCharacter.id}-turnaround.png`} download={`${sheetCharacter.id}-reference-sheet.png`} aria-label="Download reference sheet"><Download size={18}/></a><button class="icon" aria-label="Close reference sheet" onclick={()=>sheetCharacter=null}><X size={20}/></button></div></div><div class="sheet-view" class:enlarged={sheetZoom}><img src={sheetCharacter.referenceSheet||`/images/${sheetCharacter.id}-turnaround.png`} alt={`Four full-body views of ${sheetCharacter.name}: front, left profile, three-quarter, and back. Consistent futuristic fantasy costume, realistic skin and fabrics.`}/></div><div class="sheet-caption"><span><ShieldCheck size={13}/> Consistent character design</span><span>Front · Profile · Three-quarter · Back</span><span>AI-generated reference</span></div><details class="sheet-prompt"><summary><WandSparkles size={14}/> View the generation prompt <ChevronDown size={13}/></summary><p>{sheetCharacter.referencePrompt||turnaroundPrompts.find(p=>p.key===sheetCharacter.id)?.prompt||sheetCharacter.prompt}</p><button class="text-button" onclick={()=>copyText(turnaroundPrompts.find(p=>p.key===sheetCharacter.id)?.prompt||'')}><Copy size={12}/> Copy prompt</button></details></div></div>{/if}

{#if modal}<div class="modal-backdrop"><div class="dialog-modal" role="dialog" aria-modal="true" aria-label={modal==='asset-intake'?'Add '+intakeKind:modal==='asset-generation'?'Generate visual':modal==='new-project'?'Create project':modal==='new-note'?'Pin context note':modal==='project-details'?'Project details':'Workspace guide'} tabindex="-1" use:trapFocus in:fly={{y:10,duration:180}}><div class="modal-top"><span><Feather size={17}/> Enchanted Quill</span><button class="icon" aria-label="Close dialog" onclick={()=>modal=''}><X size={19}/></button></div><div class="dialog-body">{#if modal==='asset-intake'}<AssetIntake kind={intakeKind} onsave={saveIntake} oncancel={()=>modal=''}/>{:else if modal==='asset-generation'}<h2>{generationEntity.entity.name||generationEntity.entity.title}</h2><p>Review the prompt. Generation only starts when you click the generation button.</p><GenerationStudio storyId={project.id} scene={generationEntity.type==='scene'?generationEntity.entity:null} kind={generationEntity.type} entityId={generationEntity.entity.id} title={generationEntity.entity.name||generationEntity.entity.title} prompt={generationEntity.prompt} {assets} onassetschange={refreshAssets} {notify}/>{:else if modal==='new-project'}<StoryCreator oncreate={createStorySpace} oncancel={()=>modal=''}/>{:else if modal==='guide'}<span class="large-icon violet"><Feather size={25}/></span><h2>Your next great story starts here.</h2><p>A workspace for the people, places, and possibilities in your story.</p><div class="guide-row"><span>01</span><div><h3>Build the story</h3><p>Write scenes, connect choices, and arrange the timeline. Your work saves on this device.</p></div></div><div class="guide-row"><span>02</span><div><h3>Explore the world</h3><p>Inspect characters and locations. Open a reference sheet to study all four views and the exact generation prompt.</p></div></div><div class="guide-row"><span>03</span><div><h3>Follow a thread</h3><p>Use the inspector and structural checks to see how your scenes fit together. Intelligence content is a labeled design preview.</p></div></div><div class="shortcut-list"><span>Quick commands <kbd>Ctrl K</kbd></span><span>Preview current scene <kbd>Ctrl Enter</kbd></span><span>Close panels and dialogs <kbd>Esc</kbd></span></div><label class="import-button"><Upload size={14}/> Import a story<input type="file" accept="application/json,.json" onchange={importStory}/></label>{:else}<span class="large-icon violet">{#if modal==='new-note'}<Pin size={24}/>{:else}<FolderOpen size={24}/>{/if}</span><h2>{modal==='new-project'?'Make room for a new world.':modal==='new-note'?'Something worth remembering.':'The heart of your project.'}</h2><form onsubmit={(e)=>{e.preventDefault();if(modal==='new-project')createProject();else if(modal==='project-details'){project.title=newTitle.trim()||project.title;project.description=newDescription;modal='';notify('Project details updated');}else{notes.push({id:Date.now(),title:newTitle.trim(),text:newDescription,type:'Creative direction'});log('Context note pinned',newTitle,'memory');modal='';notify('Context note pinned');}}}><label>{modal==='new-note'?'Note title':'Project name'}<input required data-autofocus bind:value={newTitle} placeholder={modal==='new-note'?'A rule, a truth, an intention…':'The name of your next story'}/></label><label>{modal==='new-note'?'Context':'Logline'}<textarea bind:value={newDescription} placeholder={modal==='new-note'?'What should the story remember?':'A few words about the world you’re creating.'}></textarea></label><div class="form-actions"><button type="button" class="button secondary" onclick={()=>modal=''}>Cancel</button><button class="button primary" type="submit">{modal==='new-project'?'Create project':modal==='new-note'?'Pin note':'Save details'}<ArrowRight size={14}/></button></div></form>{/if}</div></div></div>{/if}

